from design_utils import *
DEST=ROOT/'dist/kolejne'
def cost(text='Policz koszt',cls='btn'):
 return f'<button type="button" class="{cls}" data-cost>{text}{icon()}</button>'
def nav(cls=''):
 return f'<header class="topbar {cls}">{brand()}<nav aria-label="Nawigacja"><a href="#oferta">Odkryj SEZAM</a><a href="#kontakt">Odwiedź nas</a></nav>{cost("Pożyczka", "top-cost")}</header>'
def story(title,txt,cls=''):
 return f'<section class="story {cls}"><span class="kicker">PONAD 25 LAT W GORZOWIE</span><h2>{title}</h2><p>{txt}</p></section>'
def write(slug,title,body):
 p=DEST/slug;p.mkdir(parents=True,exist_ok=True)
 p.joinpath('index.html').write_text(f'''<!doctype html><html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>SEZAM / {title}</title><meta name="description" content="SEZAM Gorzów — skup złota, biżuteria, elektronika i pożyczki pod zastaw. Pocztowa 11."><link rel="icon" href="{A}favicon.svg"><link rel="stylesheet" href="../shared/base.css"><link rel="stylesheet" href="style.css"><script defer src="../../odwazne/shared/core.js"></script><script defer src="../shared/experiences.js"></script></head><body class="{slug}"><a href="#main" class="skip">Przejdź do treści</a>{body}<footer class="legal"><span>© 2026 PUH SEZAM Sp. z o.o. · NIP 5993281276</span><span>Grafiki aranżacyjne · <a href="https://sezam.com.pl/" target="_blank" rel="noopener">Informacje o ofercie</a></span></footer><dialog id="detail-dialog" aria-labelledby="detail-title"><button class="dialog-close" aria-label="Zamknij" type="button">×</button><span class="kicker">SEZAM / MOŻLIWOŚCI</span><h2 id="detail-title"></h2><p id="detail-text"></p><div class="dialog-actions"><a class="btn" id="detail-link" target="_blank" rel="noopener"></a><a class="btn ghost" id="detail-whatsapp" target="_blank" rel="noopener">Napisz w WhatsApp</a></div></dialog><dialog id="cost-dialog" aria-labelledby="cost-title"><button class="cost-close" aria-label="Zamknij kalkulator" type="button">×</button><span class="kicker">POŻYCZKA POD ZASTAW</span><h2 id="cost-title">Policz swój plan.</h2>{calc()}</dialog></body></html>''')

